 "content": "def transform(grid):
    """Color a diagonal, alternating stripe pattern in each quadrant of a cross."""
    h, w = len(grid), len(grid[0])
    # Cross lines are color 3, which divide the blank canvas into four quadrants.
    rbar = next(r for r,row in enumerate(grid) if all(x == 3 for x in row))
    cbar = next(c for c in range(w) if all(grid[r][c] == 3 for r in range(h)))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r == rbar or c == cbar:
                continue
            # Quadrant-specific repeated 4x4 diagonal motif, with color 4.
            # Each quadrant is tiled by a diagonal pattern: one filled cell per
            # two columns in the top-left/top-right, expanding toward the cross;
            # lower quadrants use alternating horizontal bars by row.
            if r < rbar and c < cbar:
                # Pattern is determined by local distance from top/left edges.
                if (r + c) % 2 == 0 and ((r // 2) % 2 == 0 or (c // 2) % 2 == 0):
                    out[r][c] = 4
            elif r < rbar and c > cbar:
                if (c - cbar) % 2 == 1:
                    out[r][c] = 4
            elif r > rbar and c < cbar:
                if r % 2 == 1:
                    out[r][c] = 4
            else:
                if (c - cbar) % 2 == 1:
                    out[r][c] = 4
    return out
