 "content": "def transform(grid):
    """Expand the green cross into the orange distance-parity pattern."""
    h, w = len(grid), len(grid[0])
    cross_r = next(r for r, row in enumerate(grid) if all(x == 3 for x in row))
    cross_c = next(c for c in range(w) if all(grid[r][c] == 3 for r in range(h)))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r == cross_r or c == cross_c:
                continue
            u = abs(r - cross_r)
            v = abs(c - cross_c)
            # Even-distance rows fill the region v <= u and every even v;
            # odd-distance rows fill even v strictly beyond u.
            if (u % 2 == 0 and (v <= u or v % 2 == 0)) or (u % 2 == 1 and v > u and v % 2 == 0):
                out[r][c] = 4
    return out

if __name__ == "__main__":
